//! `teamtak-agent`: see the library's documentation.

use std::net::SocketAddr;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use teamtak_agent::agent::{Agent, AgentConfig};
use teamtak_agent::docker::DockerCli;
use teamtak_agent::host::HostPaths;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

#[derive(Parser)]
#[command(name = "teamtak-agent", version, about = "Host agent of TeamTAK")]
struct Cli {
    /// Secret shared with the platform (generated by install.sh).
    #[arg(long, env = "AGENT_TOKEN", hide_env_values = true, default_value = "")]
    token: String,
    #[arg(long, env = "AGENT_LISTEN", default_value = "0.0.0.0:9300")]
    listen: SocketAddr,
    /// Compose project the agent is limited to.
    #[arg(long, env = "AGENT_PROJECT", default_value = "teamtak")]
    project: String,
    /// Where the repository is mounted.
    #[arg(long, env = "AGENT_REPO_DIR", default_value = "/repo")]
    repo_dir: PathBuf,
    /// Where the backup folder is mounted.
    #[arg(long, env = "AGENT_BACKUP_DIR", default_value = "/repo/deploy/backups")]
    backup_dir: PathBuf,
    /// Where the host's /etc, /var/lib and /run are mounted, read-only.
    #[arg(long, env = "AGENT_HOST_ROOT", default_value = "/host")]
    host_root: PathBuf,
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Runs the agent.
    Serve,
    /// Prints the report once, as JSON, without starting the server.
    Report,
    /// Exits with 0 when the local agent answers (container healthcheck).
    Healthcheck,
    /// Sends one request to the local agent and prints its answer: for checks by hand and
    /// for the tests. Example: `teamtak-agent call POST /v1/services/caddy/restart`.
    Call {
        method: String,
        path: String,
        #[arg(default_value = "")]
        body: String,
    },
}

/// One HTTP request to the agent of this container.
async fn call(listen: SocketAddr, token: &str, method: &str, path: &str, body: &str, timeout: Duration) -> Result<(u16, String)> {
    if !path.starts_with('/') || path.contains(char::is_whitespace) || method.is_empty() || !method.chars().all(|c| c.is_ascii_uppercase()) {
        bail!("usage: call <METHOD> </path> [json body]");
    }
    let target = SocketAddr::from(([127, 0, 0, 1], listen.port()));
    let exchange = async {
        let mut stream = tokio::net::TcpStream::connect(target).await?;
        let request = format!(
            "{method} {path} HTTP/1.0\r\nHost: agent\r\nAuthorization: Bearer {token}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(request.as_bytes()).await?;
        let mut answer = String::new();
        stream.read_to_string(&mut answer).await?;
        anyhow::Ok(answer)
    };
    let answer = tokio::time::timeout(timeout, exchange).await.context("the agent did not answer in time")??;
    let status: u16 = answer.split_whitespace().nth(1).and_then(|s| s.parse().ok()).context("not an HTTP answer")?;
    Ok((status, answer.split_once("\r\n\r\n").map(|(_, b)| b.to_string()).unwrap_or_default()))
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()))
        .with_writer(std::io::stderr)
        .init();
    let cli = Cli::parse();
    match &cli.command {
        Command::Healthcheck => {
            let (status, _) = call(cli.listen, &cli.token, "GET", "/v1/health", "", Duration::from_secs(4)).await?;
            if status != 200 {
                bail!("the agent answered {status}");
            }
            return Ok(());
        }
        Command::Call { method, path, body } => {
            let (status, answer) = call(cli.listen, &cli.token, method, path, body, Duration::from_secs(35 * 60)).await?;
            println!("{status}");
            println!("{}", answer.trim());
            return Ok(());
        }
        Command::Serve | Command::Report => {}
    }

    let config = AgentConfig {
        token: cli.token.clone(),
        project: cli.project.clone(),
        repo_dir: cli.repo_dir.clone(),
        backup_dir: cli.backup_dir.clone(),
        host: HostPaths { root: cli.host_root.clone(), proc: PathBuf::from("/proc") },
    };
    let agent = Arc::new(Agent::new(config, Arc::new(DockerCli)));
    if let Command::Report = cli.command {
        agent.refresh_updates().await;
        println!("{}", serde_json::to_string_pretty(&agent.report().await)?);
        return Ok(());
    }

    if cli.token.len() < 32 {
        bail!("AGENT_TOKEN must be at least 32 characters: the agent refuses to run without a real secret");
    }
    // The package state is read once now, so the first report already has it.
    tokio::spawn({
        let agent = agent.clone();
        async move { agent.refresh_updates().await }
    });
    let listener = tokio::net::TcpListener::bind(cli.listen).await.with_context(|| format!("listening on {}", cli.listen))?;
    tracing::info!(listen = %cli.listen, project = %cli.project, "TeamTAK agent is listening");
    axum::serve(listener, teamtak_agent::api::router(agent))
        .with_graceful_shutdown(async {
            let mut term = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("signal handler");
            tokio::select! {
                _ = tokio::signal::ctrl_c() => {}
                _ = term.recv() => {}
            }
        })
        .await?;
    Ok(())
}
